import type { Lesson, LessonsPayload, Unit } from "@/types/lessons";
// Bundled copy of backend/app/data/lessons.json (generated by scripts/build_lessons_json.py) so lessons work offline.
import payload from "@/assets/lessons.json";

export const units: Unit[] = (payload as LessonsPayload).units;
export const allLessons: Lesson[] = units.flatMap((u) => u.lessons);

export const findLesson = (id: number): Lesson | undefined => allLessons.find((l) => l.id === id);
export const unitOfLesson = (id: number): Unit | undefined => units.find((u) => u.lessons.some((l) => l.id === id));

/** Lessons unlock in order: a lesson is open when every earlier lesson is completed. */
export function isUnlocked(lessonId: number, completed: Record<number, number>): boolean {
  const idx = allLessons.findIndex((l) => l.id === lessonId);
  if (idx < 0) return false;
  return allLessons.slice(0, idx).every((l) => completed[l.id] != null);
}

export const nextLesson = (completed: Record<number, number>): Lesson | undefined =>
  allLessons.find((l) => completed[l.id] == null);
